<script setup lang="ts">import {ref,onMounted,watch,computed} from 'vue';import {useRoute} from 'vue-router';import {useLab} from '../stores/laboratory';import {useAuth} from '../stores/auth';import {createQualification,approveQualification,downloadQualification} from '../api/qualifications';import {request} from '../api/client';import {useTask} from '../hooks/useTask';import PageTitle from '../components/common/PageTitle.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import {modes,versionStatuses} from '../constants/enums';import {number} from '../utils/format';import type {RunVersion} from '../types/domain';
const route=useRoute(),lab=useLab(),auth=useAuth(),versions=ref<RunVersion[]>([]),data=ref({title:'N02 · 限定范围资格复核',run_id:Number(route.query.run)||0,version_id:null as number|null,mode:'calibration_only',scope_low:10,scope_high:85,note:'仅用于本次观测范围内的校准关系研究，不视为原值可互换，不保证个体测量精度。'}),{busy,error,perform}=useTask();
const run=computed(()=>lab.runs.find(r=>r.id===data.value.run_id));
const runVersions=computed(()=>versions.value.filter(v=>v.run_id===data.value.run_id).sort((a,b)=>b.version_no-a.version_no));
const selectedVersion=computed(()=>runVersions.value.find(v=>v.id===data.value.version_id)||runVersions.value.find(v=>v.id===run.value?.active_version_id));
const versionLabel=(id:number|null|undefined)=>{const v=versions.value.find(x=>x.id===id);return v?`v${v.version_no}`:'原始结果';};
const presets:Record<string,string>={raw:'仅覆盖本次稳定光源与参考反射率观测范围；原值互换仅限本档案注明条件，不得外推。',calibration_only:'仅用于本次观测范围内的校准关系研究，不视为原值可互换，不保证个体测量精度。'};
async function loadVersions(){versions.value=(await request<RunVersion[]>('/runs/versions'));}
onMounted(()=>perform(async()=>{await lab.load();if(!data.value.run_id)data.value.run_id=lab.runs.find(r=>r.status==='completed')?.id||0;await loadVersions();}));
watch(()=>data.value.run_id,()=>{data.value.mode='calibration_only';data.value.version_id=null;});
watch(()=>data.value.mode,mode=>{if(Object.values(presets).includes(data.value.note))data.value.note=presets[mode];});
function submit(){perform(async()=>{await createQualification(data.value);await lab.load();data.value.title='';});}
function approve(id:number){perform(async()=>{await approveQualification(id);await lab.load();});}
</script>
<template><PageTitle index="05" title="把资格写在明确的范围里" text="每份资格固定引用一版完整参数与样本依据；研究后来重算，也不改写既有资格。"/><ErrorNotice :message="error" @retry="perform(lab.load)"/><div class="qualification-layout"><form v-if="auth.canEdit" class="research-form" @submit.prevent="submit"><h2>新的资格记录</h2><label>档案标题<input v-model="data.title" required minlength="2"></label><label>依据研究<select v-model="data.run_id"><option v-for="r in lab.runs.filter(x=>x.status==='completed')" :key="r.id" :value="r.id">#{{r.id}} {{r.name}} · v{{r.active_version_no||1}}</option></select></label><label>引用版本<select v-model="data.version_id"><option :value="null">当前启用版本（v{{run?.active_version_no||1}}）</option><option v-for="v in runVersions" :key="v.id" :value="v.id">v{{v.version_no}} · {{versionStatuses[v.status]||v.status}} · λ={{v.config?.lambda_ratio}}</option></select></label><p class="input-note" v-if="selectedVersion">本资格固定引用 v{{selectedVersion.version_no}}：λ={{selectedVersion.config?.lambda_ratio}}、X {{number(selectedVersion.config?.range_low,2)}}—{{number(selectedVersion.config?.range_high,2)}}%、允许误差 ±{{selectedVersion.config?.allowance}}、样本指纹 {{selectedVersion.result?.fingerprint?.slice(0,16)}}…。后续重算启用不会改变本档案依据。</p><label>资格用途<select v-model="data.mode"><option value="raw" :disabled="!selectedVersion?.result?.raw_eligible">原值互换（需满足数值门槛）</option><option value="calibration_only">仅供校准研究（不视为可互换）</option></select></label><p class="input-note">v{{selectedVersion?.version_no}} 实际观测X范围 {{selectedVersion?.result?.x_range?.map(v=>number(v,3)).join('—')}}%；下方范围必须包含于其中。</p><div class="form-grid two"><label>适用参考下限 %<input type="number" v-model.number="data.scope_low" min="0" max="100" step=".01" required></label><label>适用参考上限 %<input type="number" v-model.number="data.scope_high" min="0" max="100" step=".01" required></label></div><label>条件、限制与复核说明<textarea v-model="data.note" required minlength="10" maxlength="1000" rows="4"></textarea></label><button class="primary" :disabled="busy||data.scope_low>=data.scope_high">存为待复核记录 →</button></form><section class="qualification-files"><article v-for="q in lab.qualifications" :key="q.id"><div class="file-heading"><p class="eyebrow">QUALIFICATION / {{String(q.id).padStart(3,'0')}}</p><StatusBadge :status="q.status"/></div><h2>{{q.title}}</h2><div class="scope-line"><b>{{q.scope_low}}—{{q.scope_high}}<em>%</em></b><span>{{modes[q.mode]}}<small>依据研究 #{{q.run_id}} / 版本 {{versionLabel(q.version_id)}} / 参考X范围</small></span></div><p>{{q.note}}</p><footer><template v-if="q.status==='draft'&&auth.user?.role==='admin'"><button class="outline" @click="approve(q.id)" :disabled="busy">复核并批准 ✓</button></template><small v-if="q.status==='draft'">等待负责人复核</small><template v-else><small>批准人 {{q.approved_by}} · 固定引用 {{versionLabel(q.version_id)}}</small><button class="text-button" :disabled="busy" @click="perform(()=>downloadQualification(q.id))">导出该版配对与校准CSV ↓</button></template></footer></article><p v-if="!lab.qualifications.length" class="muted">尚无资格记录。完成研究后，先确定用途和适用范围。</p></section></div></template>
